/// Loads Roboto and the Material icons from the SDK, then every font in the package's FontManifest.
/// flutter_test otherwise renders all text with the Ahem test font (black boxes).
Future<void> fpLoadFonts(List<String> problems) async {
  final String? root = fp_io.Platform.environment['FLUTTER_ROOT'];
  if (root != null) {
    final String dir = '$root/bin/cache/artifacts/material_fonts';
    Future<void> load(String family, List<String> files) async {
      final fp_s.FontLoader loader = fp_s.FontLoader(family);
      for (final String name in files) {
        final fp_io.File file = fp_io.File('$dir/$name');
        if (file.existsSync()) {
          loader.addFont(file.readAsBytes().then((List<int> b) => fp_td.ByteData.sublistView(fp_td.Uint8List.fromList(b))));
        }
      }
      await loader.load();
    }

    await load('Roboto', <String>[
      'Roboto-Regular.ttf',
      'Roboto-Medium.ttf',
      'Roboto-Bold.ttf',
      'Roboto-Light.ttf',
      'Roboto-Italic.ttf',
      'Roboto-Thin.ttf',
      'Roboto-Black.ttf',
    ]);
    await load('MaterialIcons', <String>['MaterialIcons-Regular.otf']);
  }
  try {
    final String manifest = await fp_s.rootBundle.loadString('FontManifest.json');
    for (final dynamic family in fp_convert.json.decode(manifest) as List<dynamic>) {
      final fp_s.FontLoader loader = fp_s.FontLoader(family['family'] as String);
      for (final dynamic font in family['fonts'] as List<dynamic>) {
        loader.addFont(fp_s.rootBundle.load(font['asset'] as String));
      }
      await loader.load();
    }
  } catch (e) {
    problems.add('Could not load the app fonts: $e');
  }
}

void fpTakeErrors(fp_t.WidgetTester tester, List<String> problems) {
  final Object? error = tester.takeException();
  if (error == null) return;
  String text = error.toString();
  if (text.length > 4000) text = '${text.substring(0, 4000)}…';
  problems.add(text);
}

