final Set<String> fpStubbedChannels = <String>{};

/// There's no native side under flutter_test, so a native plugin call (wakelock, shared_preferences, a
/// MethodChannel to the host app…) would fail the preview. Calls nobody answers get an empty success reply
/// instead: void methods just do nothing; callers that need a value see null.
void fpStubNativeChannels(fp_t.WidgetTester tester) {
  final fp_t.TestDefaultBinaryMessenger messenger = tester.binding.defaultBinaryMessenger;
  messenger.allMessagesHandler = (String channel, fp_s.MessageHandler? handler, fp_td.ByteData? message) async {
    if (handler != null) return handler(message); // mocks set by the setup hook still win
    final fp_td.ByteData? reply = await messenger.delegate.send(channel, message);
    if (reply != null || channel.startsWith('flutter/')) return reply;
    return fpFakeReply(channel, message);
  };
}

fp_td.ByteData? fpFakeReply(String channel, fp_td.ByteData? message) {
  if (channel.startsWith('dev.flutter.pigeon.')) {
    fpStubbedChannels.add(channel.substring('dev.flutter.pigeon.'.length).split('.').first);
    return const fp_s.StandardMessageCodec().encodeMessage(<Object?>[null]);
  }
  for (final fp_s.MethodCodec codec in const <fp_s.MethodCodec>[fp_s.StandardMethodCodec(), fp_s.JSONMethodCodec()]) {
    try {
      codec.decodeMethodCall(message);
      fpStubbedChannels.add(channel);
      return codec.encodeSuccessEnvelope(null);
    } catch (_) {
      // Not this codec.
    }
  }
  return null;
}

