      loads.add(fp_m.precacheImage((element.widget as fp_m.Image).image, element));
    }
    for (final fp_m.Element element in fp_t.find.byType(fp_m.DecoratedBox).evaluate()) {
      final fp_m.Decoration decoration = (element.widget as fp_m.DecoratedBox).decoration;
